// lab-tests.js: Laboratory tests by branch (LAB): the core test data. Classic script: shares top-level names with the other js/ files (load order in index.html).
/* ---------- Laboratory tests by branch ---------- */
// rows: [name, Arabic name, sample, steps[], ranges[[parameter, range, unit]], note]; EDUCATIONAL typical adult values
const LAB=[
{id:'gen',en:'General lab practice',ar:'أساسيات العمل المختبري',t:[
['Venous blood collection (phlebotomy)','سحب الدم الوريدي','Vacuum tubes chosen from the request form',['Check the request form and identify the patient with two identifiers (full name and number or date of birth).','Confirm fasting or timing requirements and wash hands; wear gloves.','Apply the tourniquet 7–10 cm above the site for no more than 1 minute; choose the median cubital vein.','Clean with 70% alcohol and let it dry completely.','Insert the needle bevel up at 15–30°; fill tubes in the correct ORDER OF DRAW.','Release the tourniquet, withdraw the needle, press with gauze and discard the needle in the sharps box.','Invert each tube gently (EDTA 8–10 times, citrate 3–4 times); label at the bedside with name, number, date and time.'],[['Order of draw','1 Blood culture → 2 Citrate (blue) → 3 Serum (red/gold) → 4 Heparin (green) → 5 EDTA (lavender) → 6 Fluoride (grey)','']],'Wrong order carries additives between tubes (for example EDTA from a lavender tube falsely raises potassium and lowers calcium). Never take blood from the arm with an IV drip.'],
['Specimen rejection criteria','معايير رفض العيّنة','All specimens',['Check that the label matches the request form exactly.','Check the tube type matches the test.','Check volume (citrate tubes must be filled to the line, ratio 9:1).','Look for haemolysis, clots (EDTA, citrate) and lipaemia.','Check transport time and temperature.','Record the reason, inform the ward, and request a new sample.'],[['Reject when','Unlabelled or mislabelled; wrong tube; under-filled citrate; clotted EDTA/citrate; haemolysed for K, LDH, AST; too old','']],'Never relabel a sample that left the patient unlabelled.'],
['Internal quality control (Westgard)','ضبط الجودة الداخلي (قواعد Westgard)','Control materials, at least 2 levels',['Run at least two control levels at the start of every run or shift.','Plot each result on a Levey–Jennings chart (mean ± 1, 2, 3 SD).','Apply the Westgard rules before reporting any patient results.','If a rejection rule is broken, stop reporting, find the cause (reagent, calibration, instrument), correct it and rerun controls.','Record all actions in the QC log.'],[['1-2s','One control beyond 2 SD: warning, check','SD'],['1-3s','One control beyond 3 SD: reject run','SD'],['2-2s','Two consecutive controls beyond the same 2 SD: reject','SD'],['R-4s','One control +2 SD and another −2 SD: reject','SD'],['4-1s','Four consecutive beyond the same 1 SD: reject','SD'],['10x','Ten consecutive on the same side of the mean: reject','']],'Take part in external quality assessment (EQA) as well.']
]},
{id:'hem',en:'Haematology',ar:'أمراض الدم',t:[
['Complete blood count (CBC)','صورة الدم الكاملة','EDTA whole blood (lavender), 2–3 mL; test within 6 h at room temperature (up to 24 h at 4 °C)',['Check identification and look for clots or haemolysis.','Run daily controls (three levels) on the haematology analyser and accept only if within range.','Mix the sample well (8–10 gentle inversions or a roller mixer).','Aspirate the sample and run the CBC.','Review flags, histograms and delta checks.','Prepare and examine a blood film for flags, abnormal counts or a first presentation.','Validate and report with units and reference ranges.'],[['Haemoglobin (Hb)','M 13.5–17.5 · F 12.0–15.5','g/dL'],['Red cell count (RBC)','M 4.5–5.9 · F 4.0–5.2','×10¹²/L'],['Haematocrit (Hct/PCV)','M 41–53 · F 36–46','%'],['MCV','80–100','fL'],['MCH','27–33','pg'],['MCHC','32–36','g/dL'],['RDW-CV','11.5–14.5','%'],['White cell count (WBC)','4.0–11.0','×10⁹/L'],['Platelets','150–450','×10⁹/L']],'Many healthy people of African origin have lower neutrophil and WBC counts (benign ethnic neutropenia, WBC down to about 3.0 ×10⁹/L). Children and pregnant women have different ranges.'],
['WBC differential (blood film)','العدّ التفريقي لكريات الدم البيضاء','EDTA blood within 3 h, or capillary blood',['Place a small drop of blood near one end of a clean slide.','Spread with a spreader at 30–45° to make a film with a feathered tail; air dry quickly.','Leishman: cover the film with undiluted stain for 1–2 minutes (the methanol in the stain fixes it), add twice the volume of buffered water pH 6.8, mix gently and leave 8–10 minutes. (For Giemsa: fix in absolute methanol 2–3 minutes first, then stain with diluted Giemsa.)','Wash off with buffered water pH 6.8 (do not pour the stain off first, to avoid precipitate) and air dry upright.','Examine the monolayer under oil (100×) in a battlement pattern.','Count 100 white cells and classify them; comment on red cell and platelet morphology.','Calculate absolute counts: % × total WBC.'],[['Neutrophils','2.0–7.5 (40–75%)','×10⁹/L'],['Lymphocytes','1.0–4.0 (20–45%)','×10⁹/L'],['Monocytes','0.2–0.8 (2–10%)','×10⁹/L'],['Eosinophils','0.04–0.4 (1–6%)','×10⁹/L'],['Basophils','0–0.1 (0–1%)','×10⁹/L']],'Report absolute counts, not only percentages. Eosinophilia in Sudan: think of parasites (schistosomiasis, hookworm, filaria).'],
['Erythrocyte sedimentation rate (ESR, Westergren)','سرعة الترسيب','Venous blood with 3.8% sodium citrate, 4 parts blood : 1 part citrate (or EDTA diluted 4:1 with citrate or saline); test within 4 h',['Mix blood and anticoagulant gently.','Fill the Westergren tube to the 0 mark with no air bubbles.','Place it exactly vertical in the rack at 18–25 °C, away from sunlight and vibration.','Start the timer.','Read the height of the clear plasma column after exactly 60 minutes.'],[['ESR men','0–15 (over 50 years: 0–20)','mm/h'],['ESR women','0–20 (over 50 years: 0–30)','mm/h']],'Raised in infection, inflammation, anaemia, pregnancy, myeloma and TB. Very high (>100) suggests myeloma, TB, malignancy or vasculitis.'],
['Reticulocyte count','عدّ الخلايا الشبكية','EDTA blood',['Mix equal volumes (2–3 drops each) of blood and new methylene blue in a small tube.','Incubate at 37 °C for 15–20 minutes.','Remix and make thin films; air dry (do not fix).','Under oil, count reticulocytes (blue granular network) among 1000 red cells (a Miller ocular helps).','Calculate: reticulocytes ÷ 1000 × 100 = %; absolute = % × RBC count.'],[['Reticulocytes','0.5–2.5','%'],['Absolute reticulocytes','25–100','×10⁹/L']],'High after bleeding or haemolysis and after iron/B12 therapy; low in aplasia and nutritional deficiency.'],
['Sickling test (sodium metabisulphite)','اختبار التمنجل','EDTA blood',['Prepare fresh 2% sodium metabisulphite solution.','Mix one drop of blood with one to two drops of reagent on a slide.','Cover with a coverslip and seal the edges with petroleum jelly.','Keep at room temperature; examine after 30 minutes and again up to 24 hours.','Look for sickled or holly-leaf shaped red cells; run a known positive control.'],[['Sickling test','Negative','']],'A positive test does not separate sickle trait (AS) from disease (SS); confirm with Hb electrophoresis or HPLC.'],
['Iron studies','دراسة الحديد','Serum (plain or gel tube), morning fasting sample preferred',['Collect serum, avoid haemolysis.','Separate within 2 hours.','Calibrate and run controls on the chemistry or immunoassay analyser.','Measure iron, TIBC (or transferrin) and ferritin.','Calculate transferrin saturation = iron ÷ TIBC × 100.'],[['Serum iron','10–30','µmol/L'],['TIBC','45–72','µmol/L'],['Transferrin saturation','20–50','%'],['Ferritin','M 30–400 · F 15–150','µg/L']],'Ferritin rises in inflammation and liver disease, so a normal ferritin does not exclude iron deficiency in sick patients.'],
['Vitamin B12 and folate','فيتامين ب12 وحمض الفوليك','Serum, protected from light; fasting preferred',['Collect serum and protect from light.','Avoid haemolysis (red cells contain folate).','Run on the immunoassay analyser with controls.'],[['Vitamin B12','200–900 (148–664 pmol/L)','pg/mL'],['Serum folate','> 4 (> 9 nmol/L)','ng/mL']],'Macrocytosis with hypersegmented neutrophils suggests B12 or folate deficiency.'],
['Haemoglobin electrophoresis and HbA2 / HbF quantitation','الترحيل الكهربائي للهيموغلوبين وقياس HbA2 و HbF','EDTA whole blood (lavender cap) with the full blood count (MCV, MCH); record any recent blood transfusion',['Check the request: clinical indication, family or antenatal context, and any recent transfusion (donor blood changes the pattern).','Prepare a haemolysate from the red cells (or use the analyser’s automatic haemolysis).','Screen and quantify with HPLC or capillary electrophoresis (HbA, HbA2, HbF and variants), or with alkaline electrophoresis on cellulose acetate at pH 8.4–8.6.','Run normal and abnormal controls (for example an A, F, S, C control) with every batch.','Alkaline electrophoresis: read the bands from the anode end: A, then F, then S, then C, which runs with A2, E and O-Arab near the origin.','Confirm every variant by a second method: acid (citrate agar, pH about 6.0–6.3) electrophoresis separates C from A2, E and O-Arab, and S from D and G; a sickle solubility test supports HbS.','Interpret with the blood count, blood film and iron status; refer for DNA analysis when α-thalassaemia or a rare variant is suspected.'],[['HbA2 (adult, educational)','about 2.0–3.5 (method-dependent: use the local range)','%'],['HbA2 in β-thalassaemia trait','> 3.5','%'],['HbF (adult)','< 1','%'],['Sickle cell trait (HbAS)','HbA more than HbS; HbS about 35–45 %',''],['Sickle cell anaemia (HbSS)','HbS main band, no HbA; HbF variable','']],'Iron deficiency (and α-thalassaemia) lowers HbA2 and can hide β-thalassaemia trait: repeat after iron treatment if HbA2 is borderline. After a transfusion the result reflects donor blood.']
]},
{id:'coag',en:'Coagulation',ar:'التخثر',t:[
['Prothrombin time (PT / INR)','زمن البروثرومبين','3.2% sodium citrate (blue), filled exactly to the line (9:1); test within 24 h',['Collect a clean venepuncture (draw a discard tube first if using a butterfly).','Invert gently 3–4 times; reject clotted or under-filled tubes.','Centrifuge at 1500 g for 15 minutes to get platelet-poor plasma.','Pre-warm plasma and thromboplastin reagent to 37 °C.','Add reagent to plasma and measure the clotting time (in duplicate on manual methods).','Calculate INR = (patient PT ÷ mean normal PT)^ISI.'],[['PT','11–13.5 (laboratory specific)','seconds'],['INR (not on warfarin)','0.8–1.2',''],['INR on warfarin','2.0–3.0 (mechanical valve 2.5–3.5)','']],'A very high haematocrit (>55%) needs less citrate in the tube.'],
['Activated partial thromboplastin time (APTT)','زمن الثرومبوبلاستين الجزئي المنشّط','Citrated platelet-poor plasma; test within 4 h',['Prepare platelet-poor plasma as for PT.','Mix plasma with APTT reagent and incubate at 37 °C for 3–5 minutes.','Add pre-warmed calcium chloride and start timing.','Record the clotting time.'],[['APTT','25–35 (laboratory specific)','seconds']],'Prolonged in haemophilia A/B, heparin therapy, lupus anticoagulant and liver disease; do a 50:50 mixing study to separate factor deficiency from an inhibitor.'],
['Fibrinogen (Clauss) and D-dimer','الفيبرينوجين ودي-دايمر','Citrated plasma',['Prepare platelet-poor plasma.','Fibrinogen: dilute plasma, add high-concentration thrombin and read against the calibration curve.','D-dimer: run the immunoassay with controls.'],[['Fibrinogen','2.0–4.0','g/L'],['D-dimer','< 0.5','mg/L FEU']],'D-dimer rises with age, pregnancy, surgery and infection; it is most useful to EXCLUDE thrombosis when low.']
]},
{id:'chem',en:'Clinical chemistry',ar:'الكيمياء السريرية',t:[
['Blood glucose (fasting and random)','سكر الدم (صائم وعشوائي)','Fluoride-oxalate (grey) plasma, or serum separated within 30 min; fasting 8–12 h for FBS',['Confirm fasting status and time of last meal.','Collect into a fluoride tube (glucose falls about 5–7% per hour in plain tubes).','Centrifuge and separate.','Run controls, then measure (glucose oxidase or hexokinase method).','Report with the sample type and fasting status.'],[['Fasting glucose','3.9–5.5 (70–99 mg/dL)','mmol/L'],['Impaired fasting glucose','5.6–6.9 (100–125 mg/dL)','mmol/L'],['Diabetes (fasting)','≥ 7.0 (≥ 126 mg/dL), confirm on repeat','mmol/L'],['Random glucose, diabetes','≥ 11.1 (≥ 200 mg/dL) with symptoms','mmol/L'],['Hypoglycaemia','< 3.9 (< 70 mg/dL)','mmol/L']],'Values below 2.8 mmol/L (50 mg/dL) or above 25 mmol/L are critical: phone the clinician.'],
['Oral glucose tolerance test (OGTT)','اختبار تحمّل الجلوكوز','Fluoride plasma at 0 and 120 min (pregnancy: 0, 60, 120 min)',['Normal diet for 3 days, then fast 8–14 hours overnight.','Take the fasting sample (do not continue if fasting glucose is already diagnostic).','Give 75 g anhydrous glucose in 250–300 mL water, drunk within 5 minutes.','Patient rests seated, no food, no smoking, water only.','Take the 2-hour sample (and the 1-hour sample in pregnancy).'],[['2-hour glucose, normal','< 7.8 (< 140 mg/dL)','mmol/L'],['Impaired glucose tolerance','7.8–11.0','mmol/L'],['Diabetes','≥ 11.1 (≥ 200 mg/dL)','mmol/L'],['Gestational diabetes (any one)','Fasting ≥ 5.1 · 1 h ≥ 10.0 · 2 h ≥ 8.5','mmol/L']],''],
['HbA1c (glycated haemoglobin)','الهيموجلوبين السكري','EDTA blood; no fasting needed',['Mix the sample well.','Run on HPLC or an NGSP/IFCC-certified immunoassay with controls.','Check the chromatogram for haemoglobin variants.'],[['Normal','< 5.7 (< 39 mmol/mol)','%'],['Prediabetes','5.7–6.4 (39–47 mmol/mol)','%'],['Diabetes','≥ 6.5 (≥ 48 mmol/mol)','%'],['Good control in diabetes','< 7.0 (< 53 mmol/mol)','%']],'Unreliable in sickle cell disease, haemolysis, recent transfusion and pregnancy (falsely low) and in iron deficiency (falsely high).'],
['Renal function tests','وظائف الكلى','Serum (plain or gel tube), no haemolysis; separate within 2 h',['Collect serum and allow to clot 30 minutes.','Centrifuge and separate.','Run calibrators and controls.','Measure urea, creatinine and uric acid.','Calculate eGFR (CKD-EPI) using age and sex.'],[['Urea','2.5–7.8 (15–45 mg/dL)','mmol/L'],['Creatinine','M 62–106 (0.7–1.2 mg/dL) · F 44–80 (0.5–0.9 mg/dL)','µmol/L'],['eGFR','≥ 90','mL/min/1.73 m²'],['Uric acid','M 200–430 (3.4–7.2 mg/dL) · F 140–360 (2.4–6.0 mg/dL)','µmol/L']],''],
['Electrolytes and minerals','الأملاح والمعادن','Serum or lithium-heparin plasma; NO haemolysis; never from the drip arm',['Avoid prolonged tourniquet and fist clenching (raise potassium).','Do not refrigerate whole blood before separation.','Separate within 1–2 hours.','Measure by ion-selective electrode (Na, K, Cl) and photometry (Ca, PO₄, Mg).','Check for haemolysis index before reporting potassium.'],[['Sodium (Na⁺)','135–145','mmol/L'],['Potassium (K⁺)','3.5–5.1','mmol/L'],['Chloride (Cl⁻)','98–107','mmol/L'],['Bicarbonate (HCO₃⁻)','22–29','mmol/L'],['Calcium, total','2.15–2.55 (8.6–10.2 mg/dL)','mmol/L'],['Phosphate','0.81–1.45 (2.5–4.5 mg/dL)','mmol/L'],['Magnesium','0.70–1.00','mmol/L']],'Typical critical values (each lab sets its own): K < 2.8 or > 6.2; Na < 120 or > 160 mmol/L. Correct calcium for albumin: corrected Ca = measured Ca + 0.02 × (40 − albumin g/L).'],
['Liver function tests','وظائف الكبد','Serum, no haemolysis; protect from light for bilirubin',['Collect serum and separate within 2 hours.','Protect from light (bilirubin breaks down).','Run calibrators and controls.','Measure ALT, AST, ALP, GGT, bilirubin, total protein and albumin.'],[['ALT','M < 45 · F < 35','U/L'],['AST','10–40','U/L'],['ALP (adult)','40–130','U/L'],['GGT','M < 60 · F < 40','U/L'],['Total bilirubin','3–21 (0.2–1.2 mg/dL)','µmol/L'],['Direct bilirubin','< 5 (< 0.3 mg/dL)','µmol/L'],['Total protein','60–80','g/L'],['Albumin','35–50','g/L']],'ALP is higher in children (bone growth) and pregnancy (placenta). Haemolysis falsely raises AST.'],
['Lipid profile','دهون الدم','Serum; fasting 9–12 h preferred (needed if triglycerides are high)',['Confirm fasting status.','Collect serum and separate.','Measure total cholesterol, HDL and triglycerides; LDL by direct method or by calculation.','Friedewald (mmol/L): LDL = TC − HDL − TG ÷ 2.2 (not valid if TG > 4.5 mmol/L).'],[['Total cholesterol','< 5.2 (< 200 mg/dL)','mmol/L'],['LDL cholesterol','< 3.4 (< 130 mg/dL); optimal < 2.6','mmol/L'],['HDL cholesterol','M > 1.0 (> 40 mg/dL) · F > 1.3 (> 50 mg/dL)','mmol/L'],['Triglycerides','< 1.7 (< 150 mg/dL)','mmol/L']],'Targets are lower for patients with diabetes or heart disease.'],
['Cardiac markers','مؤشرات القلب','Serum or heparin plasma; timed after chest pain onset',['Record the time of chest pain onset and sample time.','Measure high-sensitivity troponin at presentation and repeat at 1–3 hours (per local protocol).','Report the change (delta) between samples.'],[['hs-Troponin','Below the 99th percentile of the assay (e.g. hs-TnT < 14 ng/L)','ng/L'],['CK, total','M 39–308 · F 26–192','U/L'],['CK-MB','< 25','U/L']],'A rise and/or fall of troponin above the 99th percentile supports myocardial injury.'],
['Pancreatic enzymes','إنزيمات البنكرياس','Serum or lithium-heparin plasma (NOT EDTA or citrate for amylase)',['Collect serum or lithium-heparin plasma; do not use EDTA or citrate for amylase (they bind calcium and lower the result).','Separate within 2 hours; avoid haemolysis and lipaemia.','Run calibrators and two levels of controls.','Measure amylase and/or lipase.','Dilute and repeat any result above the linear range; report in U/L.'],[['Amylase','28–100','U/L'],['Lipase','13–60','U/L']],'More than 3× the upper limit supports acute pancreatitis.']
]},
{id:'endo',en:'Hormones (endocrinology)',ar:'الهرمونات',t:[
['Thyroid function tests','وظائف الغدة الدرقية','Serum; any time of day',['Collect serum and separate within 2 hours.','Ask about biotin supplements (ideally stopped at least 8 hours before, longer for high doses: they interfere with many immunoassays) and thyroid medicines.','Run calibrators and controls on the immunoassay analyser.','Measure TSH first; add FT4 (and FT3) as indicated by the TSH result or the clinical request.','Report with the method-specific reference range.'],[['TSH','0.4–4.0','mIU/L'],['Free T4','12–22 (0.9–1.7 ng/dL)','pmol/L'],['Free T3','3.1–6.8','pmol/L']],'Pregnancy needs trimester-specific ranges.'],
['Cortisol, prolactin and β-hCG','الكورتيزول والبرولاكتين وهرمون الحمل','Serum; cortisol at 08:00–09:00; prolactin at rest, 2–3 h after waking',['Record the exact sample time (cortisol has a daily rhythm).','Prolactin: patient rested, avoid stress and breast stimulation before the sample.','Run on the immunoassay analyser with controls.'],[['Cortisol (08:00–09:00)','140–690 (5–25 µg/dL)','nmol/L'],['Prolactin','M < 15 · F (non-pregnant) < 25','ng/mL'],['β-hCG (not pregnant)','< 5','IU/L']],'Macroprolactin can cause falsely high prolactin.']
]},
{id:'urine',en:'Urine analysis',ar:'تحليل البول',t:[
['Urine general examination (GUE)','فحص البول العام','10–15 mL clean-catch midstream urine in a sterile container; examine within 2 h (or refrigerate up to 24 h); first morning sample preferred',['Physical: note colour, appearance (clear/turbid) and volume.','Chemical: dip the reagent strip briefly, remove excess, read each pad at the time stated on the pack (or on a strip reader).','Microscopy: centrifuge 10 mL at about 400 g (1500–2000 rpm) for 5 minutes.','Pour off the supernatant, leaving 0.5 mL; resuspend the deposit gently.','Place one drop under a coverslip; scan 10 low-power fields (casts) then 10 high-power fields (cells, crystals, organisms).','Report averages per LPF/HPF and correlate microscopy with the strip (blood ↔ RBCs, leucocyte esterase ↔ WBCs).'],[['Colour / appearance','Pale yellow to amber / clear',''],['Specific gravity','1.005–1.030',''],['pH','4.5–8.0 (usually about 6)',''],['Protein','Negative',''],['Glucose','Negative',''],['Ketones','Negative',''],['Bilirubin','Negative',''],['Urobilinogen','Normal (0.2–1.0 mg/dL)',''],['Blood','Negative',''],['Nitrite','Negative',''],['Leucocyte esterase','Negative',''],['RBCs','0–2','/HPF'],['WBCs (pus cells)','0–5','/HPF'],['Casts','0–2 hyaline','/LPF'],['Epithelial cells','Few squamous',''],['Bacteria, yeast, parasites','None','']],'Use the Analyse tab to get an AI-assisted reading of the sediment.'],
['24-hour urine protein and albumin/creatinine ratio','بروتين البول خلال 24 ساعة ونسبة الألبومين للكرياتينين','24-hour collection in a clean container; or a spot first-morning urine for ACR',['Day 1: patient empties the bladder on waking and DISCARDS this urine; note the time.','Collect ALL urine for the next 24 hours, including the first sample on waking the next day at the same time.','Keep the container cool during collection.','In the lab, measure and record the total volume, mix well and take an aliquot.','Measure protein and creatinine; check creatinine output to confirm a complete collection.'],[['24-h urine protein','< 150','mg/24 h'],['Albumin/creatinine ratio (ACR)','< 3 (< 30 mg/g)','mg/mmol'],['24-h urine creatinine','M 8.8–17.7 · F 7.1–15.9 (≈ 1.0–2.0 g and 0.8–1.8 g)','mmol/24 h']],'ACR 3–30 mg/mmol = moderately increased albuminuria (early diabetic kidney disease).'],
['Urine pregnancy test (hCG)','اختبار الحمل في البول','First morning urine preferred',['Bring the kit and sample to room temperature.','Add the stated number of drops (usually 3) to the sample well.','Read at the stated time (usually 3–5 minutes); do not read late.','The control line must appear for a valid test.'],[['Urine hCG (not pregnant)','Negative (sensitivity about 20–25 mIU/mL)','']],'Very early pregnancy may test negative: repeat after 48–72 hours or test serum β-hCG.']
]},
{id:'para',en:'Parasitology',ar:'علم الطفيليات',t:[
['Stool general examination','فحص البراز العام','Fresh stool (walnut-size or 5 mL liquid) in a clean, dry container; liquid stool examined within 30 minutes',['Macroscopic: consistency, colour, blood, mucus, adult worms or segments.','Saline mount: mix a small portion with a drop of 0.85% saline, coverslip, scan the whole coverslip at 10× then check at 40× (motile trophozoites, ova).','Iodine mount: repeat with Lugol’s iodine to show cyst nuclei.','If negative and clinical suspicion remains, do a formol-ether concentration.','Report organisms by stage (ova, cysts, trophozoites, larvae).'],[['Appearance','Brown, formed',''],['Ova, cysts, trophozoites, larvae','None seen',''],['RBCs / pus cells','None','']],'One negative sample does not exclude infection: examine three samples on different days. Common in Sudan: S. mansoni (lateral spine), Giardia, E. histolytica (ingested RBCs), hookworm, Ascaris, H. nana.'],
['Malaria thick and thin blood films','أفلام الملاريا السميكة والرقيقة','Capillary or EDTA blood (films within 1 hour); collect before antimalarials',['Thick film: 2–3 drops spread to about 1.5 cm diameter; dry 30–60 minutes; do NOT fix.','Thin film: one small drop spread with a feathered end; air dry; fix in methanol for 30 seconds (keep methanol off the thick film).','Stain with Giemsa: 3% for 30–45 minutes or 10% for 8–10 minutes, buffered water pH 7.2.','Rinse gently with buffered water and air dry upright.','Thick film: examine at least 100 oil-immersion fields before calling negative; count parasites per 200 WBCs.','Thin film: identify species and stages; count % infected red cells in high parasitaemia.'],[['Malaria parasites','None seen in 100 oil-immersion fields',''],['Parasite density (thick film)','parasites ÷ 200 WBC × WBC count (or × 8000)','/µL']],'If negative but clinical suspicion remains, repeat every 6–12 hours for 3 sets. Use the Analyse tab (Malaria film) for an AI-assisted second look.'],
['Urine for Schistosoma haematobium','فحص البول للبلهارسيا','Terminal urine collected between 10:00 and 14:00, after light exercise; at least 10 mL',['Mix the urine well.','Filtration: pass 10 mL through a 12–20 µm polycarbonate or nylon filter; place filter on a slide with a drop of iodine or saline.','Or sedimentation: centrifuge 10 mL at 400 g for 5 minutes and examine the whole deposit.','Count eggs with a terminal spine; check viability (moving miracidium) when needed.','Report eggs per 10 mL.'],[['S. haematobium eggs','None seen','/10 mL'],['Light infection','1–49','eggs/10 mL'],['Heavy infection','≥ 50','eggs/10 mL']],'Haematuria on the dipstick supports the diagnosis in endemic areas.']
]},
{id:'micro',en:'Microbiology',ar:'الأحياء الدقيقة',t:[
['Gram stain','صبغة جرام','Smear from the specimen or a colony',['Make a thin smear, air dry and heat-fix (or methanol-fix).','Crystal violet 1 minute; rinse with water.','Gram’s iodine 1 minute; rinse.','Decolourise with acetone-alcohol for a few seconds until the run-off is clear; rinse immediately.','Counterstain with safranin or neutral red 1 minute; rinse, blot dry.','Examine under oil: Gram-positive purple, Gram-negative pink/red; report cells and organisms.'],[['Result','Depends on the site: CSF and blood normally no organisms; no pus cells','']],'Over-decolourising makes Gram-positives look negative; thick smears under-decolourise.'],
['Ziehl–Neelsen stain (AFB)','صبغة زيل نيلسن','Sputum (early morning, purulent part), 2 samples',['Smear the purulent part 2 × 3 cm, air dry and heat-fix.','Flood with carbol fuchsin and heat until steaming (do not boil) for 5 minutes; rinse.','Decolourise with 3% acid-alcohol (or 25% sulphuric acid) until faintly pink; rinse.','Counterstain with methylene blue 1 minute; rinse and dry.','Examine at least 100 oil-immersion fields along the length of the smear.','Grade the result (WHO/IUATLD).'],[['Negative','No AFB in 100 fields',''],['Scanty','1–9 AFB in 100 fields (report the number)',''],['1+','10–99 AFB in 100 fields',''],['2+','1–10 AFB per field (50 fields)',''],['3+','> 10 AFB per field (20 fields)','']],'Use GeneXpert MTB/RIF where available; microscopy misses low-burden TB.'],
['Urine culture and colony count','زراعة البول','Clean-catch midstream urine in a sterile container; culture within 2 h or refrigerate up to 24 h',['Mix the urine and inoculate with a calibrated loop (1 µL or 10 µL) onto CLED agar (or blood + MacConkey).','Incubate aerobically at 35–37 °C for 18–24 hours.','Count colonies: with a 1 µL loop each colony = 1000 CFU/mL.','Identify significant isolates (Gram stain, biochemical tests).','Do antimicrobial susceptibility testing on significant isolates.'],[['No significant growth','< 10⁴','CFU/mL'],['Significant bacteriuria','≥ 10⁵ of one organism','CFU/mL'],['May be significant','10³–10⁴ (symptomatic, catheter, males)','CFU/mL']],'Three or more organisms suggests contamination: request a new sample.'],
['Blood culture','زراعة الدم','8–10 mL per bottle in adults (1–3 mL in children); 2 sets from different sites before antibiotics',['Disinfect the bottle tops with 70% alcohol.','Clean the skin with chlorhexidine-alcohol and let it dry 30 seconds; do not touch the site again.','Inoculate aerobic then anaerobic bottles with the correct volume.','Incubate at 35–37 °C for 5 days (continuous monitoring or daily visual check).','For positives: Gram stain immediately, phone the clinician, subculture, identify and do susceptibility testing.'],[['Blood culture','No growth after 5 days','']],'Coagulase-negative staphylococci in a single bottle are usually contaminants.'],
['Antimicrobial susceptibility test (Kirby–Bauer disc diffusion)','اختبار الحساسية للمضادات الحيوية','Pure overnight colonies (18–24 h)',['Suspend 3–5 colonies in saline to match the 0.5 McFarland standard.','Within 15 minutes, swab Mueller–Hinton agar (4 mm depth) in three directions.','Apply discs within 15 minutes, at least 24 mm apart.','Incubate at 35 ± 1 °C for 16–20 hours.','Measure zone diameters in mm.','Interpret as S / I / R using the CURRENT CLSI or EUCAST tables; run control strains (e.g. E. coli ATCC 25922).'],[['Result','Sensitive / Intermediate / Resistant by zone size','mm']],'Report only drugs relevant to the organism and site; flag ESBL and MRSA.']
]},
{id:'sero',en:'Serology and immunology',ar:'المصليات والمناعة',t:[
['C-reactive protein (CRP)','البروتين التفاعلي C','Serum',['Collect serum (plain or gel tube); separate within 2 hours.','Check reagent expiry and calibration; bring reagents to the temperature the method requires.','Run two levels of controls before patient samples.','Measure CRP by immunoturbidimetry (the latex slide test is for screening only).','Dilute and repeat any result above the linear range; report in mg/L.'],[['CRP','< 5','mg/L'],['hs-CRP cardiovascular risk','< 1 low · 1–3 average · > 3 high','mg/L']],'Bacterial infection often > 100 mg/L.'],
['Rapid tests: HBsAg, HCV antibody, HIV','الاختبارات السريعة: التهاب الكبد ب، ج، الإيدز','Serum, plasma or whole blood as the kit states',['Bring the kit and sample to room temperature; check expiry.','Add the exact sample volume, then buffer if required.','Read at the stated time only.','The control line must appear for a valid result.','Record the kit lot number and result.'],[['HBsAg','Non-reactive',''],['Anti-HCV','Non-reactive',''],['HIV-1/2 antibody','Non-reactive','']],'A reactive HIV result must follow the national testing algorithm (confirm with different assays) before reporting positive.'],
['Widal test (typhoid)','اختبار فيدال','Serum; paired samples 10–14 days apart are best',['Collect serum; paired sera 10–14 days apart are best.','Bring reagents to room temperature; include positive and negative controls.','Slide screen: one drop of serum with one drop of each antigen (O, H, AH, BH); mix, rock for 1 minute and look for agglutination.','Tube titration of reactive antigens: doubling dilutions of serum in saline (1:20 to 1:640), add antigen, incubate at the temperature and time stated by the kit.','Read the highest dilution showing agglutination (O: fine granular; H: large fluffy clumps).','Report each titre; interpret only with clinical findings and culture.'],[['O and H titres','< 1:80 (endemic cut-off often 1:160)','titre']],'A single Widal result is unreliable in endemic areas. A fourfold rise in paired sera, or blood/stool culture, is needed for diagnosis.'],
['Brucella serology','فحص البروسيلا','Serum',['Collect serum; bring the serum and antigens to room temperature.','Rose Bengal screen: mix 25–30 µL serum with an equal volume of antigen on a white tile; rock for 4 minutes; any agglutination is reactive.','Run positive and negative control sera with every batch.','SAT for reactive sera: doubling dilutions of serum in saline (1:20 to 1:1280), add an equal volume of antigen.','Incubate at 37 °C for 20–24 hours.','Read the highest dilution with at least 50% agglutination (clearing of the supernatant) and report it as the titre.'],[['Rose Bengal','Negative',''],['SAT titre','< 1:80 (≥ 1:160 significant in endemic areas)','titre']],'Culture (blood, bone marrow) confirms; prolonged incubation needed.'],
['ASO and rheumatoid factor','الأجسام المضادة للستربتوليسين والعامل الروماتويدي','Serum',['Collect serum; bring the serum and latex reagents to room temperature.','Place one drop of serum and one drop of each control on the slide; add one drop of latex reagent to each.','Mix, rotate gently for 2 minutes and read immediately for agglutination.','The positive control must agglutinate and the negative control must not.','For reactive samples: test doubling dilutions in saline; titre × kit sensitivity = IU/mL (or measure by turbidimetry).'],[['ASO (adults)','< 200','IU/mL'],['Rheumatoid factor','< 14','IU/mL']],''],
['rK39 test (visceral leishmaniasis / kala-azar)','اختبار rK39 لداء الليشمانيا الحشوي','Serum or finger-prick blood',['Bring the kit and sample to room temperature; check expiry.','Add the stated volume of serum (or finger-prick blood) to the sample pad.','Add the buffer drops as instructed.','Read at the stated time (usually 10 minutes).','Valid only if the control line appears; record the kit lot number and result.'],[['rK39','Negative','']],'Antibodies persist after cure; diagnose relapse by parasitology (spleen, bone marrow or lymph node aspirate).']
]},
{id:'mol',en:'Molecular diagnostics',ar:'التشخيص الجزيئي',t:[
['Nucleic acid extraction (silica spin column)','استخلاص الأحماض النووية (أعمدة السيليكا)','EDTA whole blood, swabs in transport medium, tissue, CSF or sputum (per kit validation); store at 2–8 °C short term, −20/−80 °C long term',['Work in the pre-PCR (clean) area with filter tips, gloves and a dedicated lab coat.','Lyse the sample with chaotropic lysis buffer (guanidinium salt) and proteinase K; incubate as the kit states.','Add ethanol and load the lysate on the silica membrane column; centrifuge so nucleic acid binds.','Wash the membrane with the two wash buffers; spin dry to remove all ethanol.','Elute in low-salt elution buffer or nuclease-free water into a clean labelled tube.','Include a negative extraction control and an internal control with every batch.','Measure concentration and purity by spectrophotometry (A260, A260/280, A260/230) if required.'],[['A260/280 (pure DNA)','≈ 1.8',''],['A260/280 (pure RNA)','≈ 2.0',''],['A260/230','≈ 2.0–2.2 (lower suggests salt or phenol carry-over)',''],['Negative extraction control','No target detected','']],'Residual ethanol and guanidinium salts inhibit PCR. RNA needs RNase-free handling and fast processing.'],
['Conventional PCR and agarose gel electrophoresis','تفاعل البوليميراز المتسلسل التقليدي والرحلان الكهربائي','Extracted DNA (or cDNA after reverse transcription)',['Prepare the master mix in the clean area: buffer, MgCl₂, dNTPs, forward and reverse primers, Taq polymerase and nuclease-free water.','Add template DNA in a separate area; include a positive control and a no-template control (NTC).','Cycle in the thermal cycler: initial denaturation, then 30–35 cycles of denaturation, annealing and extension, then final extension (temperatures and times as validated for the assay).','Prepare a 1–2% agarose gel in TAE or TBE buffer with a DNA stain.','Load samples with loading dye beside a DNA size ladder.','Run at about 5 V/cm until the dye front has migrated adequately.','Visualise under UV or blue light and compare band size with the ladder.'],[['Positive control','Band of the expected size',''],['No-template control','No band',''],['Sample','Band of expected size = target detected','']],'Keep pre- and post-PCR areas physically separate (one-way workflow) to prevent amplicon contamination.'],
['Real-time PCR (qPCR)','تفاعل البوليميراز المتسلسل في الوقت الحقيقي','Extracted DNA/RNA (RNA via reverse transcription, RT-qPCR)',['Prepare the master mix with primers and fluorescent chemistry (hydrolysis probe or DNA-binding dye) in the clean area.','Add templates, standards (if quantitative), positive control, NTC and internal control.','Run the validated cycling programme; fluorescence is read every cycle.','Set the threshold in the exponential phase; record the Ct (Cq) values.','For quantification, read sample values from the standard curve.','For dye (SYBR) assays, check the melt curve for a single specific peak.'],[['Amplification efficiency','90–110% (slope −3.6 to −3.1)',''],['Standard curve linearity','R² ≥ 0.98',''],['No-template control','No amplification (no Ct)',''],['Internal control','Amplified (else result invalid)','']],'Lower Ct means more target: a 10-fold increase in target lowers Ct by about 3.3 cycles at 100% efficiency.'],
['Xpert MTB/RIF (cartridge-based NAAT)','فحص Xpert MTB/RIF للسل','Sputum (≥ 1 mL), or other validated specimens; process within the time stated by the manufacturer',['Label the cartridge with the sample ID.','Add Sample Reagent to the sputum at a 2:1 ratio (reagent : sputum) and shake vigorously.','Incubate at room temperature with intermittent shaking for the time stated in the package insert (the reagent liquefies and inactivates bacilli).','Transfer the treated sample (about 2 mL) into the cartridge sample chamber with the supplied pipette, avoiding bubbles.','Load the cartridge into the GeneXpert module and start the test.','Read the result when the run ends; check that the sample processing control and probe check passed.'],[['MTB','Detected (high/medium/low/very low; Ultra also "trace") or Not detected',''],['Rifampicin resistance','Detected / Not detected / Indeterminate',''],['Invalid / Error / No result','Repeat the test with a new cartridge','']],'Rifampicin resistance detected needs confirmation and further drug-susceptibility testing per national guidelines.'],
['High-risk HPV DNA testing','فحص الحمض النووي لفيروس الورم الحليمي عالي الخطورة','Cervical sample in an approved liquid medium (clinician- or self-collected where validated)',['Collect the cervical sample with the approved device and place it in the transport vial.','Label with two identifiers; transport and store as the assay states.','Run on the validated platform (PCR-based detection of high-risk HPV types with a human DNA internal control).','Check that the internal control is valid before reporting.','Report high-risk HPV detected/not detected, with HPV 16/18 genotyping if available.'],[['High-risk HPV','Not detected',''],['Internal control (β-globin or similar)','Valid','']],'WHO recommends HPV DNA detection as the primary screening test for cervical cancer prevention.']
]},
{id:'bank',en:'Blood bank',ar:'بنك الدم',t:[
['ABO and Rh(D) grouping (tube method)','تحديد فصيلة الدم','EDTA blood',['Prepare a 3–5% saline suspension of the patient’s red cells.','Forward group: one drop of anti-A, anti-B and anti-D in labelled tubes, add one drop of cell suspension to each.','Reverse group: two drops of patient plasma with one drop each of A₁ and B reagent cells.','Centrifuge (about 1000 g for 15–20 seconds).','Resuspend gently and read and grade agglutination (0 to 4+).','Forward and reverse groups must agree; resolve any discrepancy before issuing blood.'],[['Group A','anti-A + · anti-B − · A₁ cells − · B cells +',''],['Group B','anti-A − · anti-B + · A₁ cells + · B cells −',''],['Group AB','anti-A + · anti-B + · A₁ cells − · B cells −',''],['Group O','anti-A − · anti-B − · A₁ cells + · B cells +',''],['Rh(D)','Positive or negative (test weak D per policy)','']],'Newborns under 4 months have no reliable reverse group.'],
['Crossmatch (antiglobulin method)','اختبار التوافق','Patient EDTA/clotted sample less than 72 h old; donor segment',['Check patient identity, group, and antibody screen.','Mix 2 drops patient plasma with 1 drop 3–5% donor cells; spin and read (immediate spin).','Add LISS and incubate at 37 °C for 15 minutes.','Wash cells 3–4 times with saline, removing all saline after the last wash.','Add anti-human globulin (AHG), spin, read.','Add IgG-coated (Coombs control) cells to every negative tube; they must agglutinate.'],[['Compatible','No agglutination or haemolysis at any phase','']],'Any incompatibility: do not issue; investigate antibodies.'],
['Direct antiglobulin test (DAT / direct Coombs)','اختبار كومبس المباشر','EDTA blood',['Prepare a 3–5% suspension of patient red cells.','Wash 3–4 times with saline.','Add polyspecific AHG, centrifuge, read.','Validate negatives with Coombs control cells.'],[['DAT','Negative','']],'Positive in autoimmune haemolysis, haemolytic disease of the newborn and transfusion reactions.'],
['Antibody screen (indirect antiglobulin test)','الكشف عن الأجسام المضادة غير المتوقعة (اختبار كومبس غير المباشر)','EDTA plasma (or serum); if the patient was transfused or pregnant in the last 3 months the sample must be no more than 3 days old',['Check sample labelling against the request; record transfusion and pregnancy history.','Use 2 or 3 group O screening cells whose antigen sheet (antigram) covers the clinically important antigens (D, C, c, E, e, K, Fyᵃ, Fyᵇ, Jkᵃ, Jkᵇ, S, s, M).','Tube method: add patient plasma and LISS-suspended screening cells in the ratio the reagent states; incubate at 37 °C (about 15 minutes with LISS).','Wash 3–4 times with saline, removing all saline after the last wash.','Add anti-human globulin, centrifuge, read and grade agglutination.','Add IgG-coated control cells to every negative tube: they must agglutinate, or the test is invalid.','Column agglutination (gel) alternative: add cells and plasma to the IAT column, incubate at 37 °C, centrifuge and read as the card states.','Run a weak anti-D positive control and a negative control with each batch.'],[['Antibody screen','Negative: no agglutination or haemolysis with any screening cell',''],['Positive screen','Identify the antibody with a red cell panel; check the DAT / autocontrol','']],'A negative screen does not exclude antibodies to low-frequency antigens: the antiglobulin crossmatch detects these.']
]},
{id:'histo',en:'Histopathology',ar:'علم الأنسجة المرضية',t:[
['Specimen reception, fixation and grossing','استلام العيّنة والتثبيت والفحص العياني','Fresh tissue placed in 10% neutral buffered formalin (NBF) immediately after removal',['Check the container and request form match (two identifiers, site, clinical details); record date and time received.','Confirm the fixative volume is at least 10 times the tissue volume; open or slice large specimens so formalin can penetrate (about 1 mm per hour).','Record cold ischaemia time (removal to fixative) and time into fixative.','Grossing: orient, describe, measure and weigh; ink the surgical margins.','Cut slices and select blocks no thicker than 3–4 mm; record a cassette key (which block = which area).','Keep remaining tissue in formalin until the report is signed out.'],[['Fixative','10% NBF (4% formaldehyde, pH 6.8–7.2)',''],['Fixative : tissue volume','≥ 10 : 1 (ideally 20 : 1)',''],['Fixation time','6–72 h (breast for ER/PR/HER2: 6–72 h)',''],['Cold ischaemia time','≤ 1 h',''],['Block thickness','≤ 3–4 mm','']],'Under-fixed tissue gives poor morphology and false-negative immunohistochemistry; over-fixed tissue (> 72 h) needs stronger antigen retrieval.'],
['Tissue processing (overnight schedule)','تحضير الأنسجة الآلي (برنامج الليل)','Fixed, grossed tissue in labelled cassettes',['Load cassettes in the processor baskets; check reagent levels and the change schedule.','Run the schedule below (times for standard 3–4 mm blocks; shorten for small biopsies).','Dehydration removes water with graded alcohols; clearing with xylene removes alcohol; infiltration fills the tissue with molten paraffin wax.','Use vacuum and agitation during wax infiltration.','Rotate or replace reagents on a fixed schedule (or by cassette count).'],[['10% NBF','1 h','37 °C'],['70% alcohol','1 h',''],['90% alcohol','1 h',''],['100% alcohol × 3','1 h each',''],['Xylene × 3','1 h each',''],['Paraffin wax × 3','1 h each','56–58 °C']],'Brittle, hard tissue means over-processing or overheated wax; soft, mushy tissue that will not cut means incomplete dehydration or clearing.'],
['Embedding and microtomy','الطمر في الشمع والتقطيع','Wax-infiltrated tissue',['Embed with the correct orientation: skin and mucosa on edge (perpendicular), tubes in cross-section, cut surface facing down.','Cool the block on the cold plate; check the label.','Chill the block face on ice; trim at 10–15 µm until the full face is exposed.','Cut ribbons at 3–5 µm with a sharp disposable blade.','Float the ribbon on a water bath about 5–10 °C below the wax melting point (40–45 °C); remove wrinkles.','Pick up on clean (charged, for IHC) slides; drain and dry at 56–60 °C for 20–30 minutes.'],[['Section thickness (routine)','3–5','µm'],['Water bath','40–45','°C'],['Thick and thin sections','Loose block or blade, worn microtome',''],['Chatter (bands)','Blunt blade, tissue too hard, angle wrong',''],['Vertical scratches / splits','Nick in the blade or calcium in tissue',''],['Crumbling, holes','Poor processing (water or alcohol left in tissue)',''],['Wrinkles, folds','Water bath too cold or blade dull','']],'Never cut tissue that may contain TB or prions without the correct safety measures.'],
['Haematoxylin and eosin (H&E) staining','صبغة الهيماتوكسلين والإيوسين','Paraffin sections on slides',['Dewax in xylene, 2 changes, 3–5 minutes each.','Rehydrate through 100%, 100%, 95%, 70% alcohol to running water.','Harris haematoxylin 5–10 minutes (regressive method); rinse in water.','Differentiate in 1% acid-alcohol for a few seconds; rinse.','Blue in Scott’s tap water substitute (or running tap water) for 1–5 minutes; check nuclei under the microscope.','Eosin 1–3 minutes.','Dehydrate quickly through 95% and 100% alcohol, clear in xylene, mount with DPX.'],[['Nuclei','Blue to purple, crisp chromatin',''],['Cytoplasm, muscle','Shades of pink',''],['Red cells','Bright red / orange',''],['Collagen','Pale pink','']],'Run a control slide with each batch. Filter haematoxylin daily; change eosin when the pink turns weak.'],
['Frozen section (intra-operative)','المقطع المجمّد أثناء العملية','FRESH unfixed tissue sent immediately to the lab (never in formalin)',['Record the time received; examine and select the area to freeze.','Mount the tissue on the chuck in OCT compound and freeze it quickly.','Cut at 4–6 µm in the cryostat (fatty tissue thicker and colder).','Pick up the section on a slide and fix immediately in 95% alcohol or formalin-alcohol for 10–30 seconds.','Rapid H&E (about 3–5 minutes); dehydrate, clear, mount.','The pathologist reports to the surgeon by phone; document time and wording.','Process the remaining frozen tissue as a permanent paraffin block for comparison.'],[['Cryostat chamber','−20 to −25 (fat −30 to −35)','°C'],['Section thickness','4–6','µm'],['Turnaround time','≤ 20 minutes (one block)','']],'Freezing artefact can mimic disease; the final diagnosis rests on the paraffin sections. Disinfect the cryostat after infectious cases.'],
['Decalcification of bone and calcified tissue','إزالة الكالسيوم من العظم والأنسجة المتكلسة','Thoroughly FIXED tissue in thin slices (≤ 4–5 mm)',['Fix completely in formalin first (acid on unfixed tissue destroys morphology).','Cut thin slices with a bone saw.','Immerse in 20 times its volume of decalcifier; change the fluid daily.','Test the end point every day: chemical test, X-ray, or gentle probing.','Wash in running water (or neutralise) and then process as normal tissue.'],[['Formic acid 5–10%','Moderate speed (days); good morphology; IHC acceptable',''],['Hydrochloric or nitric acid','Rapid (hours); damages nuclei, DNA and IHC',''],['EDTA 10–14% (pH 7.0–7.4)','Slow (weeks); best for IHC and molecular tests',''],['End point (chemical)','No calcium oxalate precipitate when ammonium oxalate is added to the used fluid','']],'Over-decalcification gives pale nuclei that stain poorly with haematoxylin.'],
['PAS and PAS-diastase','صبغة بيرأيوديك أسيد شيف (PAS) مع الدياستيز','Paraffin sections (duplicate slides); control: liver or kidney',['Dewax and bring sections to water.','PAS-D slide only: treat with 1% diastase (or saliva) at 37 °C for 30–60 minutes; wash.','Periodic acid 0.5–1% for 5–10 minutes; rinse in distilled water.','Schiff reagent 15 minutes.','Wash in running warm tap water 5–10 minutes (the magenta colour develops).','Counterstain nuclei with haematoxylin; blue; dehydrate, clear and mount.'],[['Glycogen','Magenta on PAS, REMOVED by diastase',''],['Neutral mucins, fungi, basement membranes','Magenta (diastase resistant)',''],['Nuclei','Blue','']],'Use for glycogen, fungi, basement membrane thickening and α1-antitrypsin globules (PAS-D positive).'],
['Ziehl–Neelsen for tissue (AFB) and Wade–Fite','صبغة زيل نيلسن للأنسجة','Paraffin sections; known positive control',['Dewax and bring to water.','Carbol fuchsin 30 minutes at room temperature (or 10 minutes at 60 °C); wash.','Differentiate in 1% acid-alcohol until the section is pale pink; wash well.','Counterstain with methylene blue 30–60 seconds; wash.','Dehydrate quickly, clear and mount.','Wade–Fite (for leprosy): dewax in xylene–peanut oil, stain with carbol fuchsin, then differentiate gently in weak sulphuric acid (strength as in the laboratory’s validated protocol) instead of acid-alcohol.'],[['Mycobacteria','Bright red rods',''],['Background','Blue','']],'Mycobacterium leprae is weakly acid-fast: use Wade–Fite, not standard ZN.'],
['Masson trichrome','صبغة ماسون ثلاثية الألوان','Paraffin sections; control: skin or liver',['Dewax and bring to water; mordant formalin-fixed sections in Bouin’s solution 1 hour at 56 °C; wash until yellow disappears.','Weigert’s iron haematoxylin 10 minutes; wash.','Biebrich scarlet–acid fuchsin 5 minutes; rinse.','Phosphomolybdic–phosphotungstic acid 10–15 minutes.','Aniline blue (or light green) 5 minutes.','1% acetic acid 1 minute; dehydrate, clear and mount.'],[['Collagen','Blue (or green)',''],['Muscle, cytoplasm, keratin','Red',''],['Nuclei','Black','']],'Used to assess fibrosis (liver, kidney, heart) and to separate collagen from smooth muscle.'],
['Perls’ Prussian blue (iron)','صبغة بيرلز للحديد','Paraffin sections; control: tissue with haemosiderin; use iron-free glassware',['Dewax and bring to distilled water.','Freshly mix equal parts 2% potassium ferrocyanide and 2% hydrochloric acid.','Stain 20–30 minutes.','Wash well in distilled water.','Counterstain with nuclear fast red 5 minutes; dehydrate, clear and mount.'],[['Ferric iron (haemosiderin)','Blue',''],['Nuclei','Red','']],'Used for haemochromatosis, haemosiderosis and bone marrow iron stores.'],
['Congo red (amyloid)','صبغة الكونغو الحمراء للأميلويد','Paraffin sections cut THICKER (8–10 µm); control: known amyloid',['Dewax and bring to water.','Stain nuclei with haematoxylin; blue.','Alkaline sodium chloride solution 20 minutes.','Alkaline Congo red solution 20 minutes.','Dehydrate quickly in absolute alcohol, clear and mount.','Examine under polarised light.'],[['Amyloid (bright field)','Pink to red',''],['Amyloid (polarised light)','Apple-green birefringence',''],['Nuclei','Blue','']],'Apple-green birefringence is required; red colour alone is not diagnostic.'],
['Grocott methenamine silver (fungi)','صبغة جروكوت الفضية للفطريات','Paraffin sections; control: known fungal tissue; acid-cleaned glassware',['Dewax and bring to distilled water.','Oxidise in 5% chromic acid 1 hour; wash.','1% sodium metabisulphite 1 minute; wash.','Working methenamine silver at 60 °C until fungi in the control turn dark brown (15–30 minutes; check under the microscope).','Tone in 0.1% gold chloride; 2% sodium thiosulphate 2 minutes; wash.','Counterstain with light green; dehydrate, clear and mount.'],[['Fungi, Pneumocystis','Black',''],['Background','Green','']],'Important in Sudan for mycetoma (Madurella) and other deep fungal infections.'],
['Alcian blue (pH 2.5) and AB-PAS','صبغة الألشيان الزرقاء','Paraffin sections; control: small intestine or colon',['Dewax and bring to water.','3% acetic acid 3 minutes.','Alcian blue pH 2.5 for 30 minutes; wash.','For AB-PAS: continue with periodic acid and Schiff as in PAS.','Counterstain with nuclear fast red (AB) or haematoxylin (AB-PAS); dehydrate, clear and mount.'],[['Acid mucins','Blue',''],['Neutral mucins (AB-PAS)','Magenta',''],['Mixed mucins (AB-PAS)','Purple','']],'Used to show intestinal metaplasia (goblet cells) in Barrett’s oesophagus and stomach.'],
['Reticulin (Gordon and Sweet)','صبغة الريتيكولين','Paraffin sections; control: liver; acid-cleaned glassware',['Dewax and bring to water; oxidise in acidified potassium permanganate 5 minutes.','Bleach in 1% oxalic acid; wash.','Sensitise in 2.5% iron alum 15 minutes; wash in distilled water.','Ammoniacal silver solution 10–15 seconds; rinse in distilled water.','Reduce in 10% formalin 1–2 minutes; tone in 0.2% gold chloride; fix in 5% sodium thiosulphate.','Counterstain if needed; dehydrate, clear and mount.'],[['Reticulin fibres','Black',''],['Nuclei','Grey to black','']],'Ammoniacal silver can become explosive when it dries: make fresh, never store, and neutralise before discarding.'],
['Immunohistochemistry (IHC), polymer method','الكيمياء المناعية النسيجية','3–4 µm sections on charged slides; positive and negative controls on every run',['Dewax and bring to water.','Heat-induced epitope retrieval: citrate pH 6.0 or Tris-EDTA pH 9.0 at 95–100 °C for 20 minutes; cool 20 minutes.','Block endogenous peroxidase: 3% hydrogen peroxide 10 minutes; wash in buffer (TBS or PBS).','Protein block if required.','Primary antibody at the validated dilution and time.','Polymer–HRP detection system; wash between every step.','DAB chromogen 5 minutes; wash in water.','Haematoxylin counterstain; blue; dehydrate, clear and mount.'],[['Positive result','Brown (DAB) in the expected cell compartment: nuclear, cytoplasmic or membranous',''],['Positive control','Expected staining present',''],['Negative control','No specific staining','']],'Never let sections dry during the run. Interpret only when controls are correct.'],
['Von Kossa (calcium salts)','صبغة فون كوسا لأملاح الكالسيوم','Formalin-fixed paraffin sections that were NOT decalcified; control: tissue with known calcification; acid-cleaned glassware and distilled water',['Dewax and bring sections to distilled water.','5% silver nitrate for 30–60 minutes under an ultraviolet lamp or a 100 W incandescent lamp, until calcium deposits in the control are black.','Rinse in several changes of distilled water.','5% sodium thiosulphate 2–3 minutes to remove unreacted silver.','Wash in running tap water 2 minutes, then 2 changes of distilled water.','Nuclear fast red 5 minutes; wash again (tap water 2 minutes, 2 changes of distilled water).','Dehydrate quickly in 3 changes of absolute alcohol, clear and mount in a synthetic resin.'],[['Calcium salts (mass deposits)','Black',''],['Dispersed calcium','Grey',''],['Nuclei','Red',''],['Cytoplasm','Pink','']],'Shows the phosphate and carbonate of calcium salts, not calcium itself. Never decalcify the block. Typical uses: Michaelis–Gutmann bodies in malakoplakia, psammoma bodies, and calcification in breast, prostate, vessels and kidney.'],
['Giemsa for Helicobacter pylori (gastric biopsy)','صبغة جيمزا للملوية البوابية في خزعة المعدة','Gastric biopsy fixed in 10% NBF; paraffin sections 3 µm; control: known H. pylori-positive gastric biopsy',['Dewax and bring to distilled water.','Place promptly in methanol, 2 changes.','Jenner’s working solution (1 part stock : 1 part distilled water, freshly made) 6 minutes.','Working Giemsa (2.4 mL stock in 50 mL distilled water, freshly made; do not reuse) 10 minutes.','Differentiate in 0.1% acetic acid one slide at a time, agitating gently and checking under the microscope until the detail is clear. Do not over-differentiate.','Dehydrate quickly (tert-butyl alcohol), clear in xylene and mount.'],[['Helicobacter pylori','Blue curved or S-shaped rods in surface mucus and gastric pits',''],['Background','Light purple','']],'Search the mucus over the surface epithelium and inside the gastric pits. Over-differentiation removes the blue from the bacteria.'],
['Tissue Gram stain (Brown–Hopps)','صبغة غرام للأنسجة (براون–هوبس)','10% NBF paraffin sections, about 6 µm (not Bouin-fixed); control with Gram-positive and Gram-negative bacteria',['Dewax and bring to distilled water.','1% crystal violet 2 minutes; rinse in distilled water.','Gram’s iodine 5 minutes; rinse in distilled water.','Decolorise in Cellosolve about 5–10 seconds, until blue no longer streams from the section; rinse quickly in distilled water.','0.5% basic fuchsin 5 minutes; rinse in distilled water.','Gallego’s solution 5 minutes; rinse well in distilled water and blot lightly without letting the section dry.','1.5% tartrazine for 3 seconds; blot off the excess at once.','Cellosolve 3 changes (6 quick dips each), xylene 3 changes (10 dips each); mount in a synthetic resin.'],[['Gram-positive bacteria','Blue',''],['Gram-negative bacteria','Red',''],['Background','Yellow','']],'The decolorising, rinsing and tartrazine steps are timing-critical. Cellosolve (2-ethoxyethanol) is toxic: work in a fume hood with gloves.']
]},
{id:'cyto',en:'Cytology – techniques and normal cells',ar:'علم الخلايا – التقنيات والخلايا الطبيعية',t:[
['Smear preparation and fixation','تحضير المسحات وتثبيتها','Fresh material: FNA, scrapings, brushings, fluid sediment; clean slides labelled in pencil on the frosted end',['Label the frosted end in pencil before collecting (patient name, number, site, fixation type).','Direct smear: place a small drop near the frosted end, lay a second slide flat on it and pull apart gently without pressing (avoids crush artefact).','Make some smears for WET fixation: drop them into 95% ethanol within seconds, before any drying.','Make others for AIR-DRYING: wave or fan them so they dry within seconds.','Spray fixative (if no ethanol jar): hold the can 25–30 cm away and spray evenly; let it dry before transport.','Keep wet-fixed slides in ethanol at least 15 minutes; send with the request form.'],[['Wet fixation','95% ethanol, immediately, ≥ 15 min','for Pap'],['Spray fixative distance','25–30','cm'],['Air-dried smears','Dry within seconds','for MGG / Diff-Quik'],['Smear thickness','Monolayer area with feathered edge','']],'Never Pap-stain an air-dried smear and never MGG-stain a wet-fixed smear: label which is which.'],
['Fine-needle aspiration (FNA) technique','تقنية الشفط بالإبرة الدقيقة','Palpable or ultrasound-guided lesion; 22–25 G needle, 10 or 20 mL syringe (with or without holder)',['Confirm identity, consent and the site; palpate or locate the lesion with ultrasound.','Clean the skin; fix the lesion between two fingers.','Insert the needle; move back and forth 10–15 times in different directions (with or without suction).','Release suction BEFORE withdrawing the needle.','Detach the needle, fill the syringe with air, reattach and expel the material onto slides.','Make air-dried and wet-fixed smears; rinse the needle in saline or preservative for a cell block or flow cytometry.','Perform 2–4 passes; rapid on-site evaluation (ROSE) checks adequacy.','Press on the site for several minutes.'],[['Needle size','22–25','G'],['Passes','2–4 (until adequate)',''],['Movements per pass','10–15','']],'Bloody aspirates dilute the cells: use a finer needle and fewer movements.'],
['Papanicolaou (Pap) stain','صبغة باب','Smears fixed IMMEDIATELY in 95% ethanol (or spray fixative); liquid-based preparations',['Fix wet smears in 95% ethanol for at least 15 minutes (air drying ruins nuclear detail).','Rinse in water; Harris haematoxylin 1–3 minutes; rinse.','Differentiate briefly in 0.5% hydrochloric acid; blue in Scott’s solution or ammonia water; rinse.','95% alcohol, 2 changes.','OG-6 for 1.5–2 minutes; 95% alcohol, 2 changes.','EA-50 for 2.5–3 minutes; 95% alcohol then 100% alcohol, 2 changes each.','Clear in xylene and mount.'],[['Nuclei','Blue to black, crisp chromatin',''],['Superficial squamous cells','Pink / orange',''],['Intermediate and parabasal cells','Blue-green',''],['Keratin','Orange','']],'Filter stains daily; contaminating cells from a dirty staining line cause false positives.'],
['May-Grünwald-Giemsa (MGG) and Diff-Quik','صبغة ماي جرونفالد جيمزا وديف كويك','AIR-DRIED smears (FNA, fluids, blood)',['Air-dry the smear quickly.','MGG: May-Grünwald stain 5 minutes; then dilute with an equal volume of buffer pH 6.8 for 1–2 minutes.','Pour off and stain in Giemsa diluted 1:10 with buffer for 15 minutes.','Rinse in buffer pH 6.8 and air dry.','Diff-Quik (rapid): fixative 5 dips (1 s each), solution I 5 dips, solution II 5 dips; rinse in water; dry.'],[['Cytoplasm','Blue (shades)',''],['Nuclei','Purple',''],['Colloid, mucin, stroma, cartilage','Metachromatic magenta to purple','']],'Air-dried stains show cytoplasm and background well; Pap shows nuclear detail better: use both.'],
['Liquid-based cytology (ThinPrep / SurePath)','الخلايا بالطريقة السائلة','Cervical brush/broom, or non-gynae samples, in the manufacturer’s preservative vial',['Rinse the device in the vial IMMEDIATELY: ThinPrep – push against the bottom and swirl about 10 times; SurePath – snap the broom head into the vial.','Close the cap tightly and label the vial with two identifiers.','Load the vial on the processor: cells are dispersed, debris and blood reduced, and a thin layer transferred to the slide.','Fix the slide immediately in 95% alcohol (automatic on most processors).','Pap stain and coverslip.','Keep the residual fluid for HPV testing or repeat slides.'],[['Adequacy (cervical)','≥ 5000 well-visualised squamous cells',''],['ThinPrep cell circle','20','mm'],['SurePath cell circle','13','mm']],'Lubricant gel and heavy blood or mucus can cause unsatisfactory slides.'],
['Cytocentrifuge (Cytospin) preparation','التحضير بجهاز الطرد الخلوي','Low-cellularity fluids: CSF, urine, bronchial washings; process CSF within 1 hour',['Assemble slide, filter card and chamber in the clip; label the slide.','Add 100–500 µL of fluid to the chamber (dilute very cellular fluid; add a drop of albumin to protein-poor fluid).','Spin at low speed (often 500–1000 rpm for 5 minutes, per the manufacturer).','Remove the slide without touching the cell spot.','Air-dry for MGG, or fix immediately in 95% ethanol for Pap.'],[['Volume per chamber','100–500','µL'],['Speed / time','≈ 500–1000 rpm, 5 min (manufacturer)',''],['Cell spot','About 6 mm circle','']],'Cells in CSF degenerate quickly; refrigerate at 4 °C if delayed.'],
['Sputum and bronchial cytology','فحص خلايا البلغم والقصبات','Early-morning DEEP-cough sputum on 3 consecutive days; or bronchial washing / brushing',['Patient rinses the mouth with water, then coughs deeply (not saliva) into a wide-mouthed container.','Send fresh (or in 50% alcohol fixative if delayed).','Pick bloody, grey or solid particles and make smears between two slides; fix in 95% ethanol.','Pap stain (MGG for air-dried brushings).','Check adequacy: alveolar macrophages must be present.','Report with the WHO Reporting System for Lung Cytopathology.'],[['Adequate sample','Alveolar macrophages present',''],['Inadequate','Saliva only: squamous cells and bacteria, no macrophages','']],'Three samples on different days increase sensitivity for lung cancer.'],
['Cell block preparation','تحضير الكتلة الخلوية','Sediment from fluids or FNA needle rinses',['Centrifuge the sample and pour off the supernatant.','Clot the sediment: add a few drops of plasma and thrombin (or use 2–3% agar or HistoGel).','Wrap the clot in lens paper and place it in a cassette.','Fix in 10% NBF at least 6 hours.','Process, embed and cut as for histology; use for H&E and IHC.'],[['Result','A paraffin block containing the cells, for H&E, special stains and IHC','']],'Cell blocks allow immunohistochemistry and molecular tests on cytology samples.'],
['Normal cells – identification guide','دليل التعرّف على الخلايا الطبيعية','Any cytology preparation',['Scan at 10×: judge cellularity and pattern (flat sheets, 3-D clusters, single cells).','Use a size ruler: red cell ≈ 7 µm, neutrophil ≈ 10–12 µm, intermediate squamous nucleus ≈ 35 µm².','At 40×, study the nucleus first: size, N:C ratio, chromatin, membrane, nucleoli.','Compare every cell with the normal types below before calling it atypical.','Remember reactive and repair changes (enlarged nuclei, nucleoli) keep smooth membranes and fine chromatin.'],[['Superficial squamous cell','Large polygonal, pink/orange cytoplasm, small dark pyknotic nucleus',''],['Intermediate squamous cell','Polygonal, blue-green cytoplasm, vesicular nucleus (≈ 35 µm²): the nuclear size reference',''],['Parabasal cell','Small round cell, dense blue cytoplasm, higher N:C; many in atrophy',''],['Endocervical cell','Columnar; honeycomb sheets or picket fence; basal nucleus; mucin',''],['Endometrial cell','Small 3-D balls, scant cytoplasm, small dark nuclei',''],['Mesothelial cell','Sheets or singles, central round nucleus, two-tone cytoplasm, windows between cells',''],['Macrophage','Foamy cytoplasm, bean-shaped eccentric nucleus',''],['Urothelial umbrella cell','Large superficial cell, often bi- or multinucleated; normal',''],['Ciliated columnar cell','Terminal bar with cilia: strong evidence of a benign cell',''],['Lymphocyte','Small round cell, scant cytoplasm, ≈ 7–8 µm','']],'Normal endometrial cells in a woman aged 45 or more should be reported (Bethesda).'],
['Quality control in cytology','ضبط الجودة في علم الخلايا','All cytology slides',['Check the stain daily on a control slide (nuclear detail, cytoplasmic colours).','Filter stains and change solutions on schedule to prevent cross-contamination.','Rescreen at least 10% of negative gynaecological slides (random plus high-risk) before sign-out.','Correlate cytology with histology results and record discrepancies.','Respect screening workload limits; screen with breaks.','Join an external quality assessment scheme; review results with staff.'],[['Rescreening of negatives','≥ 10%','of gynae slides'],['Workload (US CLIA reference)','≤ 100 slides in no less than 8 hours per 24 h','slides'],['Cyto-histology correlation','Recorded for every abnormal case with biopsy','']],'Liquid-based slides count as half a slide in the CLIA workload; follow your national rules.']
]},
{id:'cpath',en:'Cytopathology – diagnosis and reporting',ar:'علم الخلايا المرضية – التشخيص والتقارير',t:[
['Cytological criteria of malignancy','معايير الخباثة في الخلايا','Well-prepared, well-stained smears or LBC slides',['Low power: cellularity, cohesion and background (tumour diathesis: necrosis, old blood, granular debris).','Medium power: architecture – 3-D crowded clusters, loss of polarity, single atypical cells.','High power: nuclear features listed below.','Weigh several criteria together; no single feature proves malignancy.','Exclude reactive, repair, radiation and degenerative changes.','Correlate with clinical and imaging findings; use a cell block and immunocytochemistry to type the tumour.'],[['Nuclear enlargement','Larger than the matching normal cell',''],['N:C ratio','High',''],['Hyperchromasia','Dark nuclei',''],['Nuclear membrane','Irregular, notched, folded',''],['Chromatin','Coarse, clumped, unevenly distributed',''],['Nucleoli','Prominent, multiple or irregular',''],['Pleomorphism','Variation in size and shape between cells',''],['Mitoses','Increased, abnormal (atypical) forms',''],['Cohesion','Reduced: many single cells',''],['Background','Tumour diathesis','']],'Repair cells can have big nucleoli but form flat cohesive sheets with streaming and smooth membranes.'],
['Cervical cytology – Bethesda System','فحص خلايا عنق الرحم – نظام بيثيسدا','Conventional smear or liquid-based sample, Pap stained',['Check specimen adequacy first (cellularity, obscuring blood or inflammation, transformation zone component).','Screen the whole slide systematically at 10×, checking suspicious cells at 40×.','Note organisms and non-neoplastic findings.','Assign the most significant epithelial abnormality.','Send all abnormal slides to the cytopathologist.','Add recommendations according to local guidelines (HPV test, colposcopy).'],[['Adequacy, conventional','≥ 8000–12000 well-visualised squamous cells',''],['Adequacy, liquid-based','≥ 5000 squamous cells',''],['Transformation zone','Report present or absent (not required for adequacy)',''],['Normal result','NILM – negative for intraepithelial lesion or malignancy',''],['Squamous abnormalities','ASC-US, ASC-H, LSIL, HSIL, squamous cell carcinoma',''],['Glandular abnormalities','AGC (endocervical / endometrial / NOS), AIS, adenocarcinoma','']],'Also report organisms (Trichomonas, Candida, HSV, shift in flora, Actinomyces) within NILM.'],
['Squamous and glandular lesions – diagnostic criteria','معايير تشخيص الآفات الحرشفية والغدية','Pap-stained cervical slide',['Find an intermediate squamous nucleus as the size reference (≈ 35 µm²).','Measure abnormal nuclei against it and check N:C ratio, chromatin and membrane.','Look for koilocytes in mature cells (LSIL).','Look for small immature cells with high N:C, singly or in syncytia (HSIL).','Check the background for tumour diathesis (carcinoma).','For glandular groups, look for crowding, feathering, rosettes and elongated stratified nuclei (AIS).'],[['ASC-US','Nuclei 2.5–3 × intermediate nucleus, slight hyperchromasia; changes short of LSIL',''],['LSIL','Mature cells; nuclei > 3 × intermediate nucleus; koilocytes (sharp perinuclear cavity); binucleation',''],['ASC-H','Small immature cells suggesting HSIL but not enough for certainty',''],['HSIL','Smaller immature cells, very high N:C, hyperchromasia, irregular membrane; singles or syncytia',''],['Squamous cell carcinoma','Tumour diathesis; bizarre keratinised (tadpole, fibre) cells or syncytia with macronucleoli',''],['AIS','Crowded strips with feathering and rosettes; elongated pseudostratified nuclei; no diathesis','']],'An HSIL or worse result needs colposcopy; follow your national cervical screening programme.'],
['Thyroid FNA – Bethesda System','خزعة الغدة الدرقية – نظام بيثيسدا','Ultrasound-guided FNA, air-dried and wet-fixed smears ± needle rinse',['Check adequacy: at least 6 groups of 10 or more well-preserved follicular cells (exceptions: abundant colloid, cyst fluid with atypia, inflammatory lesions).','Assess colloid (thin/thick), follicular pattern (macro- vs microfollicles), Hürthle cells, lymphocytes.','Look for papillary carcinoma features: nuclear grooves, pseudo-inclusions, powdery chromatin, papillae, psammoma bodies.','Assign the Bethesda category.','Correlate with ultrasound (TI-RADS); recommend repeat FNA, molecular tests or surgery as appropriate.'],[['I','Non-diagnostic',''],['II','Benign (e.g. follicular nodule, thyroiditis)',''],['III','Atypia of undetermined significance (AUS)',''],['IV','Follicular neoplasm',''],['V','Suspicious for malignancy',''],['VI','Malignant (e.g. papillary, medullary, anaplastic carcinoma)','']],'Category IV cannot separate follicular adenoma from carcinoma: capsular or vascular invasion is seen only on histology.'],
['Breast FNA – IAC Yokohama System','خزعة الثدي – نظام يوكوهاما','FNA of breast lesion (clinical or ultrasound guided)',['Check cellularity and preservation.','Look for bipolar bare nuclei and myoepithelial cells in cohesive sheets (benign clues).','Look for single intact atypical cells, loss of cohesion, nuclear pleomorphism (malignant clues).','Assign the Yokohama category.','Use the triple test: clinical, imaging and cytology must agree.'],[['1','Insufficient / inadequate',''],['2','Benign (e.g. fibroadenoma, fibrocystic change)',''],['3','Atypical',''],['4','Suspicious of malignancy',''],['5','Malignant','']],'Do not plan definitive surgery on categories 3–4 without a core biopsy.'],
['Salivary gland FNA – Milan System','خزعة الغدد اللعابية – نظام ميلان','FNA of salivary gland lesion',['Check adequacy.','Separate non-neoplastic (sialadenitis, cyst) from neoplastic lesions.','Recognise pleomorphic adenoma (chondromyxoid stroma, magenta on MGG) and Warthin tumour (oncocytes with lymphocytes).','Assign the Milan category.'],[['I','Non-diagnostic',''],['II','Non-neoplastic',''],['III','Atypia of undetermined significance (AUS)',''],['IVA','Neoplasm: benign',''],['IVB','Salivary gland neoplasm of uncertain malignant potential (SUMP)',''],['V','Suspicious for malignancy',''],['VI','Malignant','']],'Matrix-rich tumours can mimic each other: use cell block and immunocytochemistry when needed.'],
['Lymph node FNA – Sydney System','خزعة العقد اللمفاوية – نظام سيدني','FNA of lymph node; extra passes for flow cytometry, culture (TB) and cell block',['Check adequacy and the cell population (polymorphous vs monomorphous lymphoid cells).','Look for granulomas and caseous necrosis (TB is common in Sudan: send for ZN and culture).','Look for non-lymphoid malignant cells (metastatic carcinoma, melanoma).','Assign the Sydney category; lymphoma needs flow cytometry or excision biopsy.'],[['L1','Inadequate / non-diagnostic',''],['L2','Benign',''],['L3','Atypical (cells of undetermined significance / lymphoid cells of uncertain significance)',''],['L4','Suspicious for malignancy',''],['L5','Malignant','']],'Reactive nodes show a polymorphous population with tingible-body macrophages.'],
['Serous effusion cytology – International System','فحص خلايا السوائل المصلية – النظام الدولي','Fresh pleural, peritoneal or pericardial fluid (≥ 50–100 mL); refrigerate at 4 °C if delayed (24–48 h)',['Record volume, colour and appearance.','Centrifuge (about 600 g for 10 minutes).','Make smears from the sediment: air-dried (MGG) and wet-fixed (Pap).','Make a cell block for immunohistochemistry.','Separate malignant cells from reactive mesothelial cells.','Report with the International System for Serous Fluid Cytopathology.'],[['ND','Non-diagnostic',''],['NFM','Negative for malignancy (mesothelial cells, macrophages, lymphocytes)',''],['AUS','Atypia of undetermined significance',''],['SFM','Suspicious for malignancy',''],['MAL','Malignant (primary or metastatic)','']],'Use calretinin and WT-1 (mesothelial) against claudin-4, BerEP4 or MOC-31 (carcinoma) on the cell block.'],
['Urine cytology – Paris System','فحص خلايا البول – نظام باريس','Voided urine (NOT the first morning sample) on 3 different days, or bladder washing',['Record clinical details (haematuria, instrumentation, history of tumour).','Prepare cytospin or liquid-based slides; Pap stain.','Assess adequacy.','Judge nuclear features: N:C ratio ≥ 0.7 is key, with hyperchromasia, irregular membrane and coarse chromatin.','Assign the Paris category.'],[['ND','Non-diagnostic / unsatisfactory',''],['NHGUC','Negative for high-grade urothelial carcinoma',''],['AUC','Atypical urothelial cells',''],['SHGUC','Suspicious for high-grade urothelial carcinoma',''],['HGUC','High-grade urothelial carcinoma',''],['LGUN','Low-grade urothelial neoplasm','']],'Schistosoma haematobium eggs and squamous metaplasia are common in Sudan; S. haematobium raises the risk of squamous cell carcinoma of the bladder.'],
['CSF cytology','فحص خلايا السائل النخاعي','At least 1–3 mL CSF in a sterile tube; process within 1 hour',['Do a cell count in a counting chamber.','Cytospin 0.5–1 mL at low speed onto slides.','Stain air-dried slides with MGG and wet-fixed slides with Pap.','Identify cell types and look for malignant cells (leukaemia, lymphoma, metastatic carcinoma) or organisms.'],[['Cell count (adult)','0–5 (lymphocytes and monocytes)','cells/µL'],['Neutrophils','None (normally)',''],['Malignant cells','None','']],'For suspected meningitis, send separate samples for microbiology (Gram, culture, India ink for Cryptococcus).'],
['Respiratory cytology – WHO System','فحص خلايا الجهاز التنفسي – نظام منظمة الصحة العالمية','Sputum, bronchial washing or brushing, EBUS-FNA',['Check adequacy (alveolar macrophages in sputum; lesional cells in FNA).','Separate benign reactive changes (reserve cell hyperplasia, Creola bodies in asthma) from neoplasia.','Type carcinoma when possible: squamous (keratin, orangeophilia) versus adenocarcinoma (3-D groups, vacuoles, nucleoli) versus small cell (moulding, crush, salt-and-pepper chromatin).','Keep material (cell block) for immunocytochemistry and molecular testing (EGFR, ALK, PD-L1).','Assign the WHO category.'],[['1','Insufficient / inadequate / non-diagnostic',''],['2','Benign',''],['3','Atypical',''],['4','Suspicious for malignancy',''],['5','Malignant','']],'Small cell carcinoma is a clinical emergency: report it quickly.']
]}
];

